fn main() {
    let inputs = ["42", "forty-two"];

    for text in inputs {
        let parsed: Result<i32, std::num::ParseIntError> = text.parse();
        match parsed {
            Ok(n) => println!("{text} is the number {n}"),
            Err(e) => println!("{text} is not a number: {e}"),
        }
    }
}

fn double_number(text: &str) -> Result<i32, std::num::ParseIntError> {
    let n: i32 = text.parse()?;
    Ok(n * 2)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("{}", double_number("21")?);
    println!("{}", double_number("10")?);
    Ok(())
}

fn main() {
    let a: i32 = "42".parse().unwrap_or(0);
