exercise.solution:
fn parse_all(a: &str, b: &str) -> Result<i32, std::num::ParseIntError> {
    let x: i32 = a.parse()?;
    let y: i32 = b.parse()?;
    Ok(x + y)
}

fn main() {
    match parse_all("40", "2") {
        Ok(n) => println!("ok {n}"),
        Err(e) => println!("bad number: {e}"),
    }

    match parse_all("40", "x") {
        Ok(n) => println!("ok {n}"),
        Err(e) => println!("bad number: {e}"),
    }
}
